CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Authors" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ImagePath" text NOT NULL,
    "FullName_AM" text NOT NULL,
    "FullName_EN" text NOT NULL,
    "FullName_RU" text NOT NULL,
    "Autobiographical_AM" text NOT NULL,
    "Autobiographical_EN" text NOT NULL,
    "Autobiographical_RU" text NOT NULL,
    CONSTRAINT "PK_Authors" PRIMARY KEY ("Id")
);

CREATE TABLE "Genres" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BaseId" integer NOT NULL,
    "BasesIds" integer[] NOT NULL,
    "SubgenresCount" integer NOT NULL,
    "Name_AM" text NOT NULL,
    "Name_EN" text NOT NULL,
    "Name_RU" text NOT NULL,
    CONSTRAINT "PK_Genres" PRIMARY KEY ("Id")
);

CREATE TABLE "Orders" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "Status" integer NOT NULL,
    "TotalAmount" numeric NOT NULL,
    "Currency" integer NOT NULL,
    "ShippingAddress" character varying(400),
    "Description" character varying(1000),
    "CreatedAt" timestamp with time zone NOT NULL,
    "StripeCheckoutSessionId" text NOT NULL,
    CONSTRAINT "PK_Orders" PRIMARY KEY ("Id")
);

CREATE TABLE "Reviews" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BookId" integer NOT NULL,
    "UserId" uuid NOT NULL,
    "UserName" text NOT NULL,
    "Grade" integer NOT NULL,
    "Comment" character varying(1000),
    CONSTRAINT "PK_Reviews" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" uuid NOT NULL,
    "Name" character varying(30) NOT NULL,
    "Email" character varying(200) NOT NULL,
    "Phone" character varying(50) NOT NULL,
    "PasswordHash" text NOT NULL,
    "Role" integer NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "UsersRefreshTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "IsUsed" boolean NOT NULL,
    "IsRevoked" boolean NOT NULL,
    "Value" text NOT NULL,
    "UsedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_UsersRefreshTokens" PRIMARY KEY ("Id")
);

CREATE TABLE "Books" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ImagePath" text NOT NULL,
    "ImageUrl" text NOT NULL,
    "Title_AM" text NOT NULL,
    "Title_EN" text NOT NULL,
    "Title_RU" text NOT NULL,
    "Description_AM" text NOT NULL,
    "Description_EN" text NOT NULL,
    "Description_RU" text NOT NULL,
    "Rating" double precision NOT NULL,
    "GradesCount" integer NOT NULL,
    "DiscountPercent" integer,
    "DiscountDeadline" timestamp with time zone,
    "Languages" integer NOT NULL,
    "Formats" integer NOT NULL,
    "AuthorId" integer NOT NULL,
    "GenreId" integer NOT NULL,
    CONSTRAINT "PK_Books" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Books_Authors_AuthorId" FOREIGN KEY ("AuthorId") REFERENCES "Authors" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Books_Genres_GenreId" FOREIGN KEY ("GenreId") REFERENCES "Genres" ("Id") ON DELETE CASCADE
);

CREATE TABLE "OrderItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "OrderId" integer NOT NULL,
    "BookId" integer NOT NULL,
    "SubbookId" integer NOT NULL,
    "Format" integer NOT NULL,
    "Quantity" integer,
    "UnitPrice" numeric NOT NULL,
    "Subtotal" numeric NOT NULL,
    "StripeCouponId" text,
    "StripePriceId" text NOT NULL,
    CONSTRAINT "PK_OrderItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrderItems_Orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("Id") ON DELETE CASCADE
);

CREATE TABLE "BuyedSubbooks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "BookId" integer NOT NULL,
    "SubbookId" integer NOT NULL,
    "Quantity" integer,
    CONSTRAINT "PK_BuyedSubbooks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_BuyedSubbooks_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "LikedBooks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "BookId" integer NOT NULL,
    CONSTRAINT "PK_LikedBooks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_LikedBooks_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Subbooks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "BookId" integer NOT NULL,
    "StripePriceId" text NOT NULL,
    "StripeProductId" text NOT NULL,
    "StripeCouponId" text,
    "Year" integer NOT NULL,
    "Language" integer NOT NULL,
    "Format" integer NOT NULL,
    "Price" numeric NOT NULL,
    "DiscountedPrice" numeric NOT NULL,
    "Publisher" character varying(150) NOT NULL,
    "FilePath" text NOT NULL,
    "IntroductionFilePath" text NOT NULL,
    "Details" jsonb NOT NULL,
    CONSTRAINT "PK_Subbooks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Subbooks_Books_BookId" FOREIGN KEY ("BookId") REFERENCES "Books" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CartBooks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" uuid NOT NULL,
    "BookId" integer NOT NULL,
    "StripePriceId" text NOT NULL,
    "StripeCouponId" text,
    "SubbookId" integer NOT NULL,
    "Quantity" integer,
    "DiscountPercent" integer,
    "BookFormat" integer NOT NULL,
    "BookImgUrl" text NOT NULL,
    "BookTitle_AM" text NOT NULL,
    "BookTitle_EN" text NOT NULL,
    "BookTitle_RU" text NOT NULL,
    CONSTRAINT "PK_CartBooks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CartBooks_Subbooks_SubbookId" FOREIGN KEY ("SubbookId") REFERENCES "Subbooks" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CartBooks_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

INSERT INTO "Genres" ("Id", "BaseId", "BasesIds", "Name_AM", "Name_EN", "Name_RU", "SubgenresCount")
VALUES (1, 0, ARRAY[]::integer[], 'Ժանրներ', 'Genres', 'Жанры', 0);

CREATE INDEX "IX_Books_AuthorId" ON "Books" ("AuthorId");

CREATE INDEX "IX_Books_GenreId" ON "Books" ("GenreId");

CREATE INDEX "IX_BuyedSubbooks_UserId" ON "BuyedSubbooks" ("UserId");

CREATE INDEX "IX_CartBooks_SubbookId" ON "CartBooks" ("SubbookId");

CREATE INDEX "IX_CartBooks_UserId" ON "CartBooks" ("UserId");

CREATE INDEX "IX_LikedBooks_UserId" ON "LikedBooks" ("UserId");

CREATE INDEX "IX_OrderItems_OrderId" ON "OrderItems" ("OrderId");

CREATE INDEX "IX_Subbooks_BookId" ON "Subbooks" ("BookId");

SELECT setval(
    pg_get_serial_sequence('"Genres"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Genres") + 1,
        nextval(pg_get_serial_sequence('"Genres"', 'Id'))),
    false);

